import XCTest
import CryptoKit
@testable import QVaultCrypto

/// Cross-platform compatibility test: decrypt a QVAULT v1 blob produced by the
/// Android/BouncyCastle stack (JVM vector generator) with the iOS engine.
/// The Phase-1 exit gate: proves byte-level container compatibility.
///
/// Key-interop note: BouncyCastle stores the ML-KEM-768 private key as (s, hpk, nonce)
/// plus the deterministic seed; CryptoKit reconstructs from the 64-byte seed via
/// seedRepresentation. The vector generator emits the seed alongside the blob.
final class CrossPlatformTests: XCTestCase {

    // Fixture generated by Tests/QVaultVectorGen.java + BCFields.java
    // (BouncyCastle 1.85, deterministic SHA1PRNG). Regenerate: cd Tests && javac/java.
    static let kemSeedB64 = "U9s6N5GigX24qz5mDItm2DPqmD49HVwYX3Z84IW9C/swxzLx0uDew9TU3GjtOePBCpkpcSusghUsAdQ8gKZstw=="

    static let xPrivB64 = "GFN7+z3zCwEo/O6eou5MicMdhmzRBRL6O2/CYTykTlI="

    static let blobHex = ""

    static let expectedPlaintext = "Hello from Android! Cross-platform QVAULT test vector"

    func testDecryptAndroidBlob() throws {
        let kemPriv = try MLKEM768.PrivateKey(
            seedRepresentation: Data(base64Encoded: Self.kemSeedB64)!,
            publicKey: nil
        )
        let xPriv = try Curve25519.KeyAgreement.PrivateKey(
            rawRepresentation: Data(base64Encoded: Self.xPrivB64)!
        )
        let vault = HybridPQCrypto(mlkemPriv: kemPriv, xPriv: xPriv)

        let blob = Self.blobHex.hexData()
        XCTAssertEqual(blob.count, 1300)
        XCTAssertTrue(HybridPQCrypto.hasMagic(blob))

        let out = try vault.decrypt(blob)
        XCTAssertEqual(String(data: out, encoding: .utf8), Self.expectedPlaintext)
    }
}

extension String {
    func hexData() -> Data {
        var data = Data(capacity: count / 2)
        var index = startIndex
        while index < endIndex {
            let next = self.index(index, offsetBy: 2)
            guard let b = UInt8(self[index..<next], radix: 16) else { preconditionFailure("bad hex") }
            data.append(b)
            index = next
        }
        return data
    }
}
